// The AI trust layer (FOUNDATION §3.0 rule 9): ui/core/ai.js masks every request through SK.aiGuard before the provider is
// called, un-masks the answer on the device and records one row of the AI trace log per call — never the prompt.
// Real ui/core/ai.js, ui/core/ai-guard.js and ui/core/engines.js (for SKEngines.audit.aiProviders); the guard engine is
// compiled here from its TypeScript source (engines.js is generated by tools/build_engines.mjs and may not carry it yet).
// Synthetic records only; fetch is a stub that captures what would have left the device.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import { createRequire } from 'node:module';

const root = new URL('../', import.meta.url);
const read = (p) => fs.readFileSync(new URL(p, root), 'utf8');
const plain = (o) => JSON.parse(JSON.stringify(o)); /* values cross the vm realm: compare structure, not prototypes */
const require = createRequire(new URL('app/package.json', root));
const esbuild = require('esbuild');

const engines = { window: {} }; vm.runInNewContext(read('ui/core/engines.js'), engines);
const SKEnginesReal = engines.window.SKEngines;
const guardJs = esbuild.transformSync(read('app/src/engine/fusion/system/ai-guard-engine.ts'), { loader: 'ts', format: 'iife', globalName: 'AIGuard', target: 'es2020' }).code;
const guardCtx = {}; vm.runInNewContext(guardJs + '\nthis.out=AIGuard;', guardCtx);
const aiGuardEngine = guardCtx.out;

const NAMES = ['أغنام الوادي', 'مؤسسة الريان للتجارة'];
const PRIVATE = 'co-private';

/* a page-less realm: SK with what the two modules read, the engines on window, a localStorage, a fetch that records */
function realm({ withEngine = true, fetchImpl, view = 'ledger' } = {}) {
  const ls = new Map();
  const localStorage = { getItem: (k) => (ls.has(k) ? ls.get(k) : null), setItem: (k, v) => ls.set(k, String(v)), removeItem: (k) => ls.delete(k), key: (i) => [...ls.keys()][i], get length() { return ls.size; } };
  localStorage.setItem('skosif_ai_keys', JSON.stringify({ provider: 'gemini', gemini: { key: 'AIzaSyTESTKEYTESTKEYTESTKEY', model: 'gemini-2.5-flash' } }));
  const events = [];
  const subs = new Map();
  const bus = { on: (t, fn) => { (subs.get(t) || subs.set(t, new Set()).get(t)).add(fn); }, emit: (t, d) => { events.push([t, d]); (subs.get(t) || []).forEach((fn) => fn(d, t)); } };
  const toasts = [];
  const SK = { esc: (s) => String(s ?? ''), toast: (m, k) => toasts.push([m, k]), load: (k, d) => { try { const v = JSON.parse(localStorage.getItem(k)); return v ?? d; } catch { return d; } }, save: (k, v) => { localStorage.setItem(k, JSON.stringify(v)); return true; },
    bus, company: { current: () => ({ id: PRIVATE, name: 'الشركة الخاصة', locked: true }) }, gate: { current: () => 'accounting' }, store: { idbAll: async (s) => (s === 'customers' ? [{ id: 'c1', name: NAMES[1], phone: '0512345678' }] : []) }, confirm: async () => true };
  const SKEngines = withEngine ? { ...SKEnginesReal, system: { ...(SKEnginesReal.system || {}), aiGuard: aiGuardEngine } } : { ...SKEnginesReal, system: { ...(SKEnginesReal.system || {}) } };
  delete SKEngines.system.aiGuard; if (withEngine) SKEngines.system.aiGuard = aiGuardEngine;
  const calls = [];
  const fetch = fetchImpl || (async (url, init) => { calls.push({ url, init, body: JSON.parse(init.body) });
    return { ok: true, status: 200, json: async () => ({ candidates: [{ content: { role: 'model', parts: [{ text: 'راجعت [عميل-1]: اتصل على [هاتف-1] بشأن [آيبان-1]' }] }, finishReason: 'STOP' }] }) }; });
  /* in a page window === globalThis: the modules read window.SKosifCore and the bare SKosifCore alike */
  const ctx = { SKEngines, SK, SKosifCore: { view: () => view }, SKosifCompanyPlatform: { definitions: (t) => (t === 'customers' ? [{ id: 'd1', name: NAMES[0] }] : []), aiEnabled: () => true }, localStorage, fetch, crypto: {},
    console: { warn: () => {}, error: console.error, info: () => {} }, setTimeout, clearTimeout, AbortController, TextEncoder };
  ctx.window = ctx; ctx.globalThis = ctx;
  const window = ctx;
  vm.createContext(ctx);
  vm.runInContext(read('ui/core/ai.js'), ctx);
  vm.runInContext(read('ui/core/ai-guard.js'), ctx);
  return { ctx, SK, window, ls, calls, events, toasts, AI: window.SKosifAI };
}

const PROMPT = 'العميل أغنام الوادي (هاتف 0512345678، آيبان SA03 8000 0000 6080 1016 7519) اشترى من مؤسسة الريان للتجارة';
const body = () => ({ systemInstruction: { parts: [{ text: 'أنت مراجع لشركة أغنام الوادي' }] }, contents: [{ role: 'user', parts: [{ text: PROMPT }] }], generationConfig: { temperature: 0 } });

test('the provider receives tokens, never the phone, the IBAN or the master-data names; the answer comes back un-masked', async () => {
  const r = realm();
  const res = await r.AI.generate(body(), { purpose: 'ledger-review', userNote: 'اختبار' });
  assert.equal(r.calls.length, 1, 'one request left');
  const wire = JSON.stringify(r.calls[0].body);
  for (const secret of ['0512345678', 'SA03 8000', '6080', ...NAMES]) assert.ok(!wire.includes(secret), 'the wire must not carry ' + secret);
  assert.equal(r.calls[0].body.contents[0].parts[0].text, 'العميل [عميل-1] (هاتف [هاتف-1]، آيبان [آيبان-1]) اشترى من [عميل-2]');
  assert.equal(r.calls[0].body.systemInstruction.parts[0].text, 'أنت مراجع لشركة [عميل-1]');
  assert.equal(r.calls[0].body.generationConfig.temperature, 0, 'the rest of the request is untouched');
  assert.equal(res.candidates[0].content.parts[0].text, 'راجعت أغنام الوادي: اتصل على 0512345678 بشأن SA03 8000 0000 6080 1016 7519');
});

test('one trace row per call, under the company key, with the hash of the masked prompt and no prompt text', async () => {
  const r = realm();
  await r.AI.generate(body(), { purpose: 'ledger-review', userNote: 'اختبار' });
  const key = r.SK.aiGuard.KEY;
  assert.equal(key, 'skosif_ops_ai_trace');
  const hs = read('ui/core/helper-space.js');
  const HELPER_KEY = new Function('k', 'return ' + hs.match(/const HELPER_KEY=k=>([\s\S]*?); \/\* the original CRM/)[1]);
  assert.equal(HELPER_KEY(key), true, 'the trace log is company data: it must swap with the company');
  const rows = r.SK.aiGuard.trace();
  assert.equal(rows.length, 1);
  const row = rows[0];
  assert.deepEqual(Object.keys(row).sort(), ['company', 'durationMs', 'error', 'gate', 'id', 'inputBytes', 'maskedCount', 'maskedKinds', 'model', 'outcome', 'outputBytes', 'promptHash', 'provider', 'purpose', 'screen', 'ts', 'userNote']);
  assert.equal(row.company, PRIVATE); assert.equal(row.gate, 'accounting'); assert.equal(row.screen, 'ledger'); assert.equal(row.purpose, 'ledger-review');
  assert.equal(row.provider, 'gemini'); assert.equal(row.model, 'gemini-2.5-flash'); assert.equal(row.outcome, 'ok'); assert.equal(row.userNote, 'اختبار');
  assert.equal(row.maskedCount, 5); assert.deepEqual(plain(row.maskedKinds), { iban: 1, phone: 1, name: 3 });
  assert.match(row.promptHash, /^[0-9a-f]{64}$/);
  const maskedText = 'أنت مراجع لشركة [عميل-1]\nالعميل [عميل-1] (هاتف [هاتف-1]، آيبان [آيبان-1]) اشترى من [عميل-2]';
  assert.equal(row.promptHash, aiGuardEngine.sha256Hex(maskedText), 'the hash is of the masked prompt');
  assert.ok(row.inputBytes > 100 && row.outputBytes > 50 && row.durationMs >= 0);
  const stored = r.ls.get(key);
  for (const secret of ['0512345678', '6080', ...NAMES, 'راجعت']) assert.ok(!stored.includes(secret), 'the stored log must not carry ' + secret);
  assert.ok(r.events.some(([t, d]) => t === 'ai-trace' && d && d.id === row.id), 'the screen is told');
});

test('a customer table never leaves: the preflight blocks before fetch and records a blocked row', async () => {
  const r = realm();
  const dump = Array.from({ length: 50 }, (_, i) => `زبون ${i}؛ 05${String(10000000 + i)}`).join('\n');
  await assert.rejects(r.AI.generate({ contents: [{ role: 'user', parts: [{ text: 'حلّل عملاءنا:\n' + dump }] }] }, { purpose: 'bulk' }), (e) => e.code === 'ai-blocked' && /جدول عملاء/.test(e.message));
  assert.equal(r.calls.length, 0, 'nothing was sent');
  const [row] = r.SK.aiGuard.trace();
  assert.equal(row.outcome, 'blocked'); assert.equal(row.purpose, 'bulk'); assert.equal(row.maskedCount, 50); assert.match(row.error, /جدول عملاء/);
  assert.equal(row.outputBytes, 0);
});

test('a provider failure is one error row; the model fallback does not multiply rows', async () => {
  let n = 0;
  const r = realm({ fetchImpl: async () => { n++; return { ok: false, status: 500, json: async () => ({ error: { message: 'boom' } }) }; } });
  await assert.rejects(r.AI.generate(body(), { purpose: 'x' }));
  assert.ok(n >= 2, 'the fallback models were tried (' + n + ')');
  const rows = r.SK.aiGuard.trace();
  assert.equal(rows.length, 1); assert.equal(rows[0].outcome, 'error'); assert.ok(rows[0].error.length > 0); assert.equal(rows[0].maskedCount, 5);
});

test('without the compiled engine the call still works and the row says the request left unmasked', async () => {
  const r = realm({ withEngine: false });
  const res = await r.AI.generate(body(), { purpose: 'legacy' });
  assert.equal(r.calls.length, 1);
  assert.equal(res.candidates[0].content.parts[0].text, 'راجعت [عميل-1]: اتصل على [هاتف-1] بشأن [آيبان-1]');
  const [row] = r.SK.aiGuard.trace();
  assert.equal(row.outcome, 'ok'); assert.equal(row.maskedCount, 0); assert.equal(row.promptHash, ''); assert.match(row.userNote, /دون تقنيع/);
});

test('policy, clear and the screen helpers', async () => {
  const r = realm();
  assert.deepEqual(plain(r.SK.aiGuard.policy()), { maxUnmasked: 0, maxUnmaskedNames: 0, maxBytes: 600000, tableRows: 40, maskNames: true });
  r.SK.aiGuard.setPolicy({ maskNames: false, tableRows: 100, junk: 1 });
  assert.deepEqual(plain(r.SK.aiGuard.policy()), { maxUnmasked: 0, maxUnmaskedNames: 0, maxBytes: 600000, tableRows: 100, maskNames: false });
  await r.AI.generate(body(), { purpose: 'p1' });
  assert.equal(r.calls[0].body.contents[0].parts[0].text, 'العميل أغنام الوادي (هاتف [هاتف-1]، آيبان [آيبان-1]) اشترى من مؤسسة الريان للتجارة', 'names stay when the policy says so; identifiers never do');
  const s = r.SK.aiGuard.summary();
  assert.equal(s.total, 1); assert.equal(s.ok, 1); assert.deepEqual(plain(s.byPurpose), { p1: 1 });
  assert.equal(r.SK.aiGuard.filter(r.SK.aiGuard.trace(), { outcome: 'error' }).length, 0);
  r.SK.aiGuard.clear();
  assert.equal(r.SK.aiGuard.trace().length, 0);
  assert.deepEqual(r.SK.aiGuard.policy().tableRows, 100, 'clearing the rows keeps the policy');
});
